(function(){
'use strict';
const D=window.DATA,A=window.SL;
const state={page:['overview','channels','experiments','cohorts','methods'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',weeks:12,group:'All channels',query:'',sort:'act',direction:-1,tablePage:1,budgetFraction:.20,saturation:1,mde:.10,custom:false};
const titles={overview:'Overview',channels:'Channel lab',experiments:'Experiment lab',cohorts:'Cohort retention',methods:'Methods & source'};
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',channels:'M4 20V10 M10 20V4 M16 20v-8 M22 20V7',experiments:'M9 3h6 M10 3v6l-6 10a1 1 0 001 2h14a1 1 0 001-2L14 9V3 M7 15h10',cohorts:'M3 5h18v16H3z M3 10h18 M8 5v16 M13 5v16 M18 5v16 M3 15h18',methods:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2 M16 3a4 4 0 010 8 M22 21v-2a4 4 0 00-3-3.87 M13 7a4 4 0 11-8 0 4 4 0 018 0',bolt:'M13 2L3 14h8l-1 8 11-13h-8l1-7',loop:'M20 7v5h-5 M4 17v-5h5 M5.5 7a7 7 0 0112-2l2.5 3 M4 16l2.5 3a7 7 0 0012-2',pound:'M17 5a4 4 0 00-7 2v11 M7 12h9 M7 19h12',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',filter:'M3 5h18l-7 8v7l-4-2v-5z',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',arrow:'M4 12h16 M13 5l7 7-7 7',check:'M5 12l4 4L19 6',info:'M12 17v-5 M12 7h.01 M22 12a10 10 0 11-20 0 10 10 0 0120 0',target:'M21 12a9 9 0 11-9-9 M17 12a5 5 0 11-5-5 M12 12l9-9 M16 3h5v5',spark:'M12 3l2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z',code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',clock:'M12 7v5l3 2 M22 12a10 10 0 11-20 0 10 10 0 0120 0'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const $=s=>document.querySelector(s),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>new Intl.NumberFormat('en-GB').format(Math.round(x));
const money=(x,d=0)=>x===null||!Number.isFinite(x)?'—':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
const pct=(x,d=1)=>x===null||!Number.isFinite(x)?'—':`${(100*x).toFixed(d)}%`;
const pp=(x,d=1)=>x===null||!Number.isFinite(x)?'—':`${x>=0?'+':''}${(100*x).toFixed(d)} pp`;
const ptext=x=>x<.0001?'&lt; 0.0001':x.toFixed(4);
const date=(week,long=false)=>{const d=new Date(D.startDate+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+week*7);return d.toLocaleDateString('en-GB',{day:'numeric',month:'short',...(long?{year:'numeric'}:{}),timeZone:'UTC'});};
const groups=[...new Set(D.channels.map(c=>c.group))];
function nav(){ $('#nav').innerHTML=Object.entries(titles).map(([p,t])=>`<button data-action="navigate" data-page="${p}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''} title="${t}">${icon(p)}<span class="nav-label">${t}</span>${p==='channels'?'<span class="count">43</span>':''}</button>`).join('');$('#crumb').textContent=titles[state.page];}
function head(eyebrow,title,desc,ic){return `<section class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-icon">${icon(ic)}</div></section>`;}
function filters(){return `<div class="filters"><div class="filter-left"><label class="select-wrap">${icon('calendar')}<select id="period" aria-label="Signup period">${[12,8,4].map(w=>`<option value="${w}" ${state.weeks===w?'selected':''}>Last ${w} signup weeks</option>`).join('')}</select></label><label class="select-wrap">${icon('filter')}<select id="group" aria-label="Acquisition group"><option>All channels</option>${groups.map(g=>`<option ${state.group===g?'selected':''}>${g}</option>`).join('')}</select></label><button class="button subtle" data-action="reset">Reset</button></div><span class="date-note">${date(12-state.weeks)} – 11 Oct 2026 · observed through 19 Oct</span></div>`;}
function selected(){return A.select(D,state.weeks,state.group);}
function summary(){const s=selected();return A.summary(s.rows,s.costs);}
function callout(text){return `<div class="callout">${icon('info')}<div>${text}</div></div>`;}
function chartLine(series,{rate=true,label='Activation rate',height=226,maxY=.6}={}){
  if(!series.length)return '<div class="empty-block">No observations for this selection.</div>';
  const w=660,h=height,p={l:38,r:17,t:16,b:32},iw=w-p.l-p.r,ih=h-p.t-p.b;
  const max=rate?maxY:Math.max(...series.map(s=>s.value))*1.2;
  const x=i=>p.l+(series.length===1?iw/2:i*iw/(series.length-1)),y=v=>p.t+ih*(1-v/max);
  const points=series.map((s,i)=>`${x(i)},${y(s.value)}`).join(' ');
  const poly=`${x(0)},${p.t+ih} ${points} ${x(series.length-1)},${p.t+ih}`;
  return `<svg class="chart" style="height:${height}px" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}: ${series.map(s=>`${s.label}: ${rate?pct(s.value):num(s.value)}`).join('; ')}</title><defs><linearGradient id="area-${state.page}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b8d998" stop-opacity=".6"/><stop offset="1" stop-color="#d2e6bf" stop-opacity=".05"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>`<line class="grid" x1="${p.l}" y1="${y(f*max)}" x2="${w-p.r}" y2="${y(f*max)}"/><text x="${p.l-9}" y="${y(f*max)+3}" text-anchor="end">${rate?pct(f*max,0):num(f*max)}</text>`).join('')}<polygon points="${poly}" fill="url(#area-${state.page})"/><polyline points="${points}" fill="none" stroke="#39794e" stroke-width="2.5" stroke-linejoin="round"/>${series.map((s,i)=>`<circle cx="${x(i)}" cy="${y(s.value)}" r="3.5" fill="#fff" stroke="#39794e" stroke-width="2"/><circle tabindex="0" cx="${x(i)}" cy="${y(s.value)}" r="12" fill="transparent" data-tooltip="${esc(s.label+'\n'+(rate?pct(s.value):num(s.value))+' '+label+'\n'+s.note)}" aria-label="${esc(s.label+' '+pct(s.value)+' '+s.note)}"/>${i%Math.max(1,Math.round(series.length/5))===0||i===series.length-1?`<text x="${x(i)}" y="${h-9}" text-anchor="middle">${esc(s.label)}</text>`:''}`).join('')}</svg>`;
}
function statistic(label,value,foot,ic,change=null){return `<article class="stat"><div class="stat-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><div class="stat-bottom">${change?`<span class="change ${change==='Mature cohorts'?'neutral':''}">${change}</span>`:''}<span>${foot}</span></div></article>`;}
function overview(){
  const s=selected(),m=A.summary(s.rows,s.costs),cs=A.channels(D,state.weeks,state.group).filter(c=>c.n),best=[...cs].filter(c=>c.act>=30).sort((a,b)=>a.cpa-b.cpa)[0];
  const series=Array.from({length:state.weeks},(_,i)=>{const week=12-state.weeks+i,r=s.rows.filter(u=>u[1]===week),a=A.sum(r,u=>u[4]);return {label:date(week),value:r.length?a/r.length:0,n:r.length,note:`${num(a)} / ${num(r.length)} activated`};});
  const stages=[['Signed up',m.n,1],['Started building',m.started,m.n?m.started/m.n:0],['First successful build',m.act,m.n?m.act/m.n:0],['Published a project',m.published,m.n?m.published/m.n:0]];
  const drop=m.started-m.act,exp=A.experiment(D),e=A.compare(exp[0].act,exp[0].n,exp[1].act,exp[1].n);
  return head('Product intelligence','Growth, in focus.','Understand the journey. Find the opportunity. Measure what changes.','spark')+filters()+`<section class="stats">${statistic('New signups',num(m.n),'unique users in selection','users')}${statistic('7-day activation',pct(m.rate),`${num(m.act)} successful first builds`,'bolt')}${statistic('Week 4 retention',pct(m.retRate),`${num(m.ret)} / ${num(m.eligible)} eligible users`,'loop','Mature cohorts')}${statistic('Cost per activation',money(m.cpa,2),`${money(m.spend)} acquisition cost`,'pound')}</section><section class="two-col"><article class="panel"><div class="panel-head"><div><h2>Activation over time</h2><p>Share of signups reaching a first successful build within 7 days</p></div><span class="tag">Weekly cohorts</span></div>${chartLine(series)}<div class="chart-note"><span><i class="dot"></i>Activation rate</span><span>Hover a point to inspect its denominator</span></div></article><article class="panel"><div class="panel-head"><div><h2>The builder journey</h2><p>Unique users · nested 7-day funnel</p></div><span class="tag">${num(m.n)} signups</span></div>${stages.map(([name,n,share],i)=>`<div class="funnel-stage"><div class="funnel-meta"><span>${name}</span><strong>${num(n)}</strong></div><div class="funnel-bar"><span style="width:${share*100}%;background:${['#b2cd91','#8daf6c','#5d8d53','#2d6a43'][i]}"></span></div><div class="funnel-sub">${pct(share)} of all signups${i?` · ${pct(stages[i-1][1]?n/stages[i-1][1]:0)} from previous step`:''}</div></div>`).join('')}</article></section><div class="section-head"><h2>From observation to the next question</h2><span>Calculated from the selected dataset</span></div><section class="insights"><article class="insight"><div class="insight-icon">${icon('target')}</div><div><h3>The first build is the opportunity</h3><p>${num(drop)} users started building without reaching activation. What would help them finish a useful first project?</p><button data-action="navigate" data-page="experiments">Test guided onboarding →</button></div></article><article class="insight"><div class="insight-icon">${icon('channels')}</div><div><h3>${best?esc(best.name):'Check channel efficiency'}</h3><p>${best?`${money(best.cpa,2)} per activation across ${num(best.n)} signups. A useful association to investigate; channel mix alone does not establish incrementality.`:'Change the selection to compare acquisition efficiency.'}</p><button data-action="navigate" data-page="channels">Explore the 43 channels →</button></div></article><article class="insight"><div class="insight-icon">${icon('experiments')}</div><div><h3>A signal worth checking</h3><p>The separate, randomized synthetic study shows ${pp(e.diff)} activation lift. Review uncertainty, sample requirements and guardrails before a decision.</p><button data-action="navigate" data-page="experiments">Inspect the evidence →</button></div></article></section>`;
}
function channelRows(){return A.channels(D,state.weeks,state.group).filter(c=>`${c.name} ${c.group}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>typeof a[state.sort]==='string'?state.direction*a[state.sort].localeCompare(b[state.sort]):state.direction*((a[state.sort]??Infinity)-(b[state.sort]??Infinity)));}
function channelTable(){
  const rows=channelRows(),pages=Math.max(1,Math.ceil(rows.length/10));state.tablePage=Math.min(state.tablePage,pages);
  const visible=rows.slice((state.tablePage-1)*10,state.tablePage*10),th=(name,key)=>`<th scope="col"><button data-action="sort" data-sort="${key}">${name} ${state.sort===key?(state.direction===-1?'↓':'↑'):'↕'}</button></th>`;
  return `<div class="table-wrap"><table class="table"><thead><tr>${th('Acquisition channel','name')}${th('Signups','n')}${th('Activated','act')}${th('Activation','rate')}${th('W4 retention','retRate')}${th('Acq. cost','spend')}${th('Cost / activated','cpa')}</tr></thead><tbody>${visible.map(c=>`<tr><td class="channel-name"><strong>${esc(c.name)}</strong><span>${esc(c.group)}</span></td><td>${num(c.n)}</td><td>${num(c.act)}</td><td><span class="mini-bar"><i style="width:${c.rate*100}%"></i></span>${pct(c.rate)}</td><td title="${num(c.ret)} retained / ${num(c.eligible)} eligible">${pct(c.retRate)}</td><td>${money(c.spend)}</td><td>${money(c.cpa,2)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No channels match this search.</td></tr>'}</tbody></table></div><div class="table-pagination"><span>${rows.length?`${(state.tablePage-1)*10+1}–${Math.min(state.tablePage*10,rows.length)}`:'0'} of ${rows.length} channels</span><div class="pagination-buttons">${Array.from({length:pages},(_,i)=>`<button data-action="table-page" data-index="${i+1}" class="${state.tablePage===i+1?'active':''}" aria-label="Channel table page ${i+1}" ${state.tablePage===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</div></div>`;
}
function budgetResult(){
  // Optimiser always uses all 12 weeks and every paid channel, independently of table filters.
  const o=A.optimise(A.channels(D,12,'All channels'),state.budgetFraction,state.saturation);
  return {o,html:`<div class="budget"><div><div class="eyebrow">Budget allocation sandbox</div><h2>Same budget. Different possibilities.</h2><p>A concave response model across 16 paid channels. All 12 weeks; separate from the table filters.</p><label class="range-label" for="budget-slider"><span>Maximum change per channel</span><span class="range-value">±${Math.round(state.budgetFraction*100)}%</span></label><input id="budget-slider" aria-label="Maximum budget change per channel" type="range" min="0" max="30" step="5" value="${Math.round(state.budgetFraction*100)}"><div class="sensitivity"><span class="small" style="font-size:10px;color:#aac0aa">Saturation assumption:</span>${[[.6,'Stronger'],[1,'Baseline'],[1.8,'Weaker']].map(([v,l])=>`<button data-action="saturation" data-value="${v}" class="${state.saturation===v?'selected':''}">${l}</button>`).join('')}</div></div><div class="budget-result"><span class="small" style="color:#afc6b3">Modelled activation opportunity</span><div class="metric-value" id="budget-lift">+${pct(o.lift)}</div><strong>+${num(Math.max(0,o.expected-o.base))} expected activations · ${money(o.total)} fixed budget</strong><p style="margin-top:9px">Hypothetical scenario. This is a sensitivity model, not a fitted causal marketing-mix model or a measured result.</p></div></div><div class="panel" style="margin-bottom:19px"><div class="panel-head" style="margin-bottom:10px"><div><h2>Where the scenario moves spend</h2><p>Top increases and decreases under the chosen constraints</p></div><button class="button secondary" data-action="export-budget">${icon('download')}Export scenario</button></div><div class="allocation-list">${[...o.rows.slice(0,2),...o.rows.slice(-2)].map(c=>`<div class="allocation-item"><span>${esc(c.name)}</span><strong class="${c.change>=0?'positive':'negative'}">${c.change>=0?'+':''}${pct(c.change)}</strong><span>${money(c.spend)} → ${money(c.allocated)}</span></div>`).join('')}</div></div>`};
}
function channels(){return head('43-channel commercial analytics','Put every channel in perspective.','Inspect acquisition efficiency, then challenge a budget allocation scenario.','channels')+filters()+`<div id="budget-section">${budgetResult().html}</div><article class="panel"><div class="panel-head"><div><h2>Channel performance</h2><p>Observed outcomes · first-touch attribution · maturity-adjusted retention</p></div><div class="table-controls"><input class="search" id="channel-search" aria-label="Search channels" placeholder="Search 43 channels…" value="${esc(state.query)}"><button class="button secondary" data-action="export-channels">${icon('download')}CSV</button></div></div><div id="channel-table">${channelTable()}</div></article>${callout('<p><strong>Association is a starting point.</strong> Cost per activation includes assigned acquisition costs. Different audiences and intent can explain channel differences. The sandbox assumes diminishing returns and should motivate a randomized test, not justify a budget change on its own.</p>')}`;}
function getExperiment(){const arms=A.experiment(D);return {arms,result:A.compare(arms[0].act,arms[0].n,arms[1].act,arms[1].n),ret:A.compare(arms[0].ret,arms[0].n,arms[1].ret,arms[1].n),quality:A.compare(arms[0].good,arms[0].n,arms[1].good,arms[1].n)};}
function intervalChart(r){
  const width=530,h=105,min=Math.min(-.015,r.ci[0]-.015),max=Math.max(.07,r.ci[1]+.015),x=v=>40+(v-min)/(max-min)*450;
  return `<svg style="width:100%;height:105px" viewBox="0 0 ${width} ${h}" role="img" aria-label="Absolute effect ${pp(r.diff,2)}; 95 percent confidence interval ${pp(r.ci[0],2)} to ${pp(r.ci[1],2)}"><line x1="40" x2="490" y1="53" y2="53" stroke="#e5eadf"/><line x1="${x(0)}" x2="${x(0)}" y1="13" y2="77" stroke="#a5b396" stroke-dasharray="3 3"/><text x="${x(0)}" y="95" text-anchor="middle" font-size="9" fill="#8b987f">No effect</text><line x1="${x(r.ci[0])}" x2="${x(r.ci[1])}" y1="45" y2="45" stroke="#66964f" stroke-width="5" stroke-linecap="round"/><circle cx="${x(r.diff)}" cy="45" r="6" fill="#234c32" stroke="white" stroke-width="2"/><text x="${x(r.ci[0])}" y="24" text-anchor="middle" font-size="10" fill="#71915d">${pp(r.ci[0],2)}</text><text x="${x(r.ci[1])}" y="24" text-anchor="middle" font-size="10" fill="#71915d">${pp(r.ci[1],2)}</text><text x="${x(r.diff)}" y="72" text-anchor="middle" font-size="10" fill="#315632">${pp(r.diff,2)}</text></svg>`;
}
function planner(){const n=A.sampleSize(.40,state.mde),pre=A.sampleSize(.40,.10);return `<article class="panel planner"><div class="panel-head"><div><h2>Plan before looking</h2><p>Two-sided α = 5% · power = 80%</p></div>${icon('target')}</div><label class="range-label" for="mde-slider" style="font-size:11px">Minimum detectable relative lift <strong class="range-value" id="mde-label">${pct(state.mde,0)}</strong></label><input id="mde-slider" type="range" min="5" max="20" step="1" value="${state.mde*100}" aria-label="Minimum detectable relative lift"><div class="planner-values"><span>5% · smaller effect</span><span>20% · larger effect</span></div><div class="metric-value" id="sample-size">${num(n)}</div><p class="small">users required <strong>per arm</strong></p><div class="math-note" id="planner-detail">Baseline 40.0% → target ${pct(.4*(1+state.mde))}. Approximate equal-allocation two-proportion power calculation.</div><div class="callout" style="margin-bottom:0;padding:12px"><p>The synthetic study’s original plan stays fixed at <strong>${num(pre)} users per arm and a 10% relative MDE</strong>. Exploring this slider does not change its stopping rule.</p></div></article>`;}
function experimentResults(x,custom=false){
  const {arms,result:r,ret,quality}=x,required=A.sampleSize(.4,.1),enough=arms.every(a=>a.n>=required),safe=!custom&&ret.ci[0]>-.02&&quality.ci[0]>-.02,significant=r.ci[0]>0;
  const pooled=(arms[0].act+arms[1].act)/(arms[0].n+arms[1].n),normalApprox=arms.every(a=>Math.min(a.n*pooled,a.n*(1-pooled))>=5);
  const total=arms[0].n+arms[1].n,chi=((arms[0].n-total/2)**2+(arms[1].n-total/2)**2)/(total/2);
  // chi-square(1) survival = two-sided standard-normal tail at sqrt(chi).
  const t=1/(1+.2316419*Math.sqrt(chi)),d=.3989422804014327*Math.exp(-chi/2),srmP=2*d*t*(.319381530+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));
  const decision=custom?'Interpret the effect in context':!enough?'Continue to the planned sample':srmP<.001?'Investigate the assignment imbalance':significant&&safe?'A candidate for a staged rollout':!safe?'Investigate the guardrails':'Keep the current experience';
  const detail=custom?'Custom inputs have no verified randomization, study horizon or guardrails. This calculator does not make a rollout decision.':!enough?'The pre-specified sample requirement has not been reached in both arms.':srmP<.001?'Sample-ratio mismatch is a reason to check instrumentation and assignment before interpreting lift.':significant&&safe?'In this synthetic study, the planned sample and observation window are complete, activation is higher, and both guardrails clear the −2 pp margin.':'Assess the full confidence intervals and the original study plan. A positive point estimate alone is not a sufficient decision rule.';
  return `<div class="two-equal">${arms.map((a,i)=>`<article class="panel arm-card ${i?'variant':''}"><div class="arm-top"><div class="arm-title"><span class="arm-marker">${i?'B':'A'}</span>${i?'Guided first project':'Current onboarding'}</div><span class="tag">${i?'Variant':'Control'}</span></div><div class="metric-value">${pct(a.act/a.n)}</div><span class="small">7-day activation rate</span><div class="metric-strip"><div><strong>${num(a.n)}</strong><span>assigned users</span></div><div><strong>${num(a.act)}</strong><span>activated users</span></div><div><strong>${pct(A.wilson(a.act,a.n)[0])}–${pct(A.wilson(a.act,a.n)[1])}</strong><span>95% Wilson interval</span></div></div></article>`).join('')}</div><div class="explanation-grid"><article class="panel"><div class="panel-head" style="margin-bottom:5px"><div><h2>The estimated activation effect</h2><p>Variant minus control · percentage points</p></div><span class="status ${r.ci[0]>0?'':'warn'}">${r.ci[0]>0?'95% interval above zero':'Uncertainty includes zero'}</span></div>${intervalChart(r)}<div class="metric-strip" style="margin-top:4px"><div><strong>${pp(r.diff,2)}</strong><span>absolute lift</span></div><div><strong>${r.relative!==null?(r.relative>=0?'+':'')+pct(r.relative):'—'}</strong><span>relative lift</span></div><div><strong>${normalApprox?ptext(r.p):'Not reliable'}</strong><span>two-sided z-test p-value</span></div></div><div class="math-note">About <strong>${num(r.diff*10000)} additional activations per 10,000 signups</strong> under this synthetic scenario; 95% interval ${num(r.ci[0]*10000)} to ${num(r.ci[1]*10000)}. The interval uses Newcombe’s difference of Wilson proportions.${normalApprox?'':' Sparse or degenerate counts make the normal-approximation p-value unreliable; use an exact test before interpreting significance.'}</div></article>${planner()}</div><div class="decision ${custom||!enough||!safe||!significant||srmP<.001?'amber':''}"><div class="decision-icon">${icon(!custom&&enough&&safe&&significant&&srmP>=.001?'check':'info')}</div><div><h2>${decision}</h2><p>${detail}</p></div></div>${!custom?`<article class="panel"><div class="panel-head" style="margin-bottom:2px"><div><h2>A win needs guardrails</h2><p>Intention-to-treat: all assigned users remain in each denominator</p></div><span class="tag">Pre-specified non-inferiority margin: −2 pp</span></div>${[[ret,'Week 4 retention','Activity on days 28–34 after signup'],[quality,'Error-free first session','Assigned users with an error-free first builder session']].map(([g,label,desc])=>`<div class="guardrail"><div><h3>${label}</h3><p>${desc} · ${pct(g.p1)} → ${pct(g.p2)}</p></div><div style="text-align:right"><span class="status ${g.ci[0]>-.02?'':'warn'}">${g.ci[0]>-.02?'Clears margin':'Needs investigation'}</span><p>${pp(g.diff,2)} · 95% CI ${pp(g.ci[0],2)} to ${pp(g.ci[1],2)}</p></div></div>`).join('')}<div class="guardrail"><div><h3>Assignment integrity</h3><p>50:50 user-level allocation · ${num(arms[0].n)} control / ${num(arms[1].n)} variant</p></div><div style="text-align:right"><span class="status ${srmP<.001?'warn':''}">${srmP<.001?'Check assignment':'No SRM flag'}</span><p>χ²(1) p = ${ptext(srmP)} · flag threshold 0.001</p></div></div></article>`:''}`;
}
function experiments(){const x=getExperiment();return head('Experimentation & causal thinking','An uplift is only the beginning.','A randomized synthetic onboarding test, with uncertainty and a decision rule you can inspect.','experiments')+`<div class="switch-row"><div class="experiment-meta"><span class="tag">${D.experiment.start} → ${D.experiment.end}</span><span class="tag">Mature 4-week follow-up</span><span class="tag">User-level randomization</span></div><div class="segmented"><button data-action="experiment-mode" data-mode="demo" class="${!state.custom?'active':''}">Seeded study</button><button data-action="experiment-mode" data-mode="custom" class="${state.custom?'active':''}">Try your numbers</button></div></div>${state.custom?customInputs(x):`<div id="experiment-results">${experimentResults(x)}</div>`}${callout('<p><strong>What is being tested?</strong> A guided first-project flow versus the current onboarding. The primary metric is successful first build within 7 days. The study plan is fixed before inspecting results; repeated peeking and choosing favourable segments would invalidate a simple fixed-horizon interpretation. Results here are simulated, not evidence about any real product.</p>')}`;}
function customInputs(x){return `<article class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h2>Explore a two-arm comparison</h2><p>Whole-number counts only. No data is uploaded or stored.</p></div><span class="tag">Local calculation</span></div><div class="input-grid">${x.arms.map((a,i)=>`<div><h3 style="margin-bottom:13px">${i?'Variant B':'Control A'}</h3><label class="field">Assigned users<input type="number" min="1" max="10000000" id="n${i}" value="${a.n}" aria-label="${i?'Variant':'Control'} assigned users"></label><label class="field">Activated users<input type="number" min="0" id="x${i}" value="${a.act}" aria-label="${i?'Variant':'Control'} activated users"></label></div>`).join('')}</div><div id="input-error" class="error" role="alert"></div><button class="button" data-action="calculate-experiment">Calculate comparison →</button></article><div id="custom-results"></div>`;}
function cohorts(){
  const sel=selected(),m=A.summary(sel.rows,sel.costs),maxK=8;
  const cells=Array.from({length:state.weeks},(_,i)=>{const w=12-state.weeks+i,rows=sel.rows.filter(r=>r[1]===w);return {w,rows};});
  const aggregate=Array.from({length:maxK+1},(_,k)=>{const rows=sel.rows.filter(r=>k<=11-r[1]),n=rows.length,ret=A.sum(rows,r=>(r[6]&(1<<k))?1:0);return {label:'W'+k,value:n?ret/n:0,note:`${num(ret)} / ${num(n)} eligible users`,n};}).filter(p=>p.n);
  return head('Cohort analysis','Retention that respects time.','Compare point retention only after a cohort has completed the observation window.','cohorts')+filters()+`<section class="stats">${statistic('Week 4 retention',pct(m.retRate),'weighted by eligible cohort size','loop')}${statistic('Eligible for Week 4',num(m.eligible),'fully matured signup cohorts','users')}${statistic('Returned in Week 4',num(m.ret),'active on days 28–34','bolt')}${statistic('Recent signups excluded',num(m.n-m.eligible),'no premature churn classification','clock')}</section><article class="panel"><div class="panel-head"><div><h2>When builders come back</h2><p>Percentage of each signup cohort active in the indicated week</p></div><span class="tag">Point retention · not survival</span></div><div class="table-wrap"><table class="cohort-table"><thead><tr><th scope="col">Signup cohort</th>${Array.from({length:maxK+1},(_,k)=>`<th scope="col">Week ${k}</th>`).join('')}</tr></thead><tbody>${cells.map(({w,rows})=>`<tr><td>${date(w)}<span class="cohort-size">${num(rows.length)} users</span></td>${Array.from({length:maxK+1},(_,k)=>{if(k>11-w||!rows.length)return '<td class="censored" title="Full cohort follow-up is not available" aria-label="Not yet mature">—</td>';const n=A.sum(rows,r=>(r[6]&(1<<k))?1:0),v=n/rows.length;return `<td style="background:hsl(94 32% ${96-v*64}%);color:${v>.65?'#f1f7e8':'#3c6430'}" title="${num(n)} / ${num(rows.length)} users; ${pct(v)}">${pct(v,0)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="legend"><span>Lower</span>${[.05,.2,.4,.65,1].map(v=>`<i style="background:hsl(94 32% ${96-v*64}%)"></i>`).join('')}<span>Higher · — not yet mature</span></div></article><section class="two-equal" style="margin-top:20px"><article class="panel"><div class="panel-head"><div><h2>The weighted retention curve</h2><p>Eligible users at each week · composition changes with maturity</p></div></div>${chartLine(aggregate,{label:'point retention',maxY:1,height:210})}</article><article class="panel"><div class="panel-head"><div><h2>Read the triangle, not the blanks</h2><p>Three details that change the interpretation</p></div></div><div class="definition"><strong>Week 0 is 100% by definition.</strong><p>Every user is active at signup. Subsequent weeks measure a return, and need not decline monotonically.</p></div><div class="definition"><strong>A blank is not a zero.</strong><p>Recent cohorts have not completed later weeks. They are excluded from both numerator and denominator.</p></div><div class="definition"><strong>Do not average percentages.</strong><p>The aggregate rate divides all returning eligible users by all eligible users, so small cohorts do not receive disproportionate weight.</p></div></article></section>`;
}
function checks(){
 const ids=new Set(D.rows.map(r=>r[0])),idsOk=ids.size===D.rows.length,funnel=D.rows.every(r=>r[5]<=r[4]&&r[4]<=r[3]),channelsOk=D.rows.every(r=>r[2]>=0&&r[2]<D.channels.length),bounds=D.rows.every(r=>r[1]>=0&&r[1]<12&&r[6]<(1<<(12-r[1]))),costs=D.costs.every(r=>r[2]>=0),exp=D.rows.filter(r=>r[7]).every(r=>r[1]<4);
 return [[idsOk,'Unique user IDs',`${num(ids.size)} distinct records`],[funnel,'Valid nested funnel','Published ≤ activated ≤ started'],[channelsOk,'Channel integrity','Every channel reference resolves'],[bounds,'Observation boundaries','No retention beyond maturity'],[costs,'Non-negative costs','516 cohort-channel cost records'],[exp,'Experiment boundaries','Assignment only in planned window']];
}
function methods(){const quality=checks();return head('Methods, provenance & reproducibility','Make the reasoning inspectable.','The data contract, statistical choices and source behind every chart.','methods')+`<section class="about-banner"><div class="avatar">VR</div><div><h2>Vikas Reddy Konreddy</h2><p>A portfolio prototype connecting commercial analytics experience at Axtria with postgraduate study in Advanced Computer Science at the University of Hertfordshire. The 43-channel sandbox is inspired by marketing optimisation work; the product funnel and experiment show how those analytical foundations transfer to software growth.</p><div class="pill-row"><span class="pill">SQL & Python</span><span class="pill">Commercial analytics</span><span class="pill">Experiment design</span><span class="pill">Data quality</span><span class="pill">AI-assisted build</span></div></div></section><section class="checks">${quality.map(([ok,label,detail])=>`<div class="check"><span class="status ${ok?'':'warn'}">${icon(ok?'check':'info')}</span><div><h3>${label}</h3><p>${detail}</p></div></div>`).join('')}</section><div class="method-grid"><article class="panel"><div class="panel-head"><div><h2>The metric contract</h2><p>Explicit numerators, denominators and windows</p></div></div>${[['7-day activation','Users with a first successful project within 7 days / all signups. Every displayed signup has completed its 7-day window.'],['Published project','Published within 7 days. Publication is a subset of activation, which is a subset of starting the builder.'],['Week 4 point retention','Activity on days 28–34 after signup / signups in fully matured cohorts. The youngest member must have completed the window. With this data snapshot, signup weeks 0–7 qualify.'],['Acquisition cost per activation','Allocated channel acquisition costs / activated users. Organic costs include allocated content or operating effort. It is not lifetime value, contribution margin or incremental acquisition cost.'],['A/B population','All 7,505 assigned users in the first four signup cohorts. Analyze by original assignment, including those who never open the builder. The experiment does not respond to dashboard segment filters.']].map(([a,b])=>`<div class="definition"><strong>${a}</strong><p>${b}</p></div>`).join('')}</article><article class="panel"><div class="panel-head"><div><h2>Statistical and modelling choices</h2><p>Useful precision, with limits attached</p></div></div>${[['Uncertainty','Individual conversion rates: 95% Wilson intervals. Difference in proportions: Newcombe’s unpooled difference-of-Wilson method. Two-sided pooled two-proportion z-test for the primary p-value.'],['Study plan','Baseline 40%; minimum detectable relative lift 10% (4 percentage points); two-sided α 5%, power 80%. Equal-allocation normal-approximation sample size. The stopping rule remains fixed when the planning slider moves.'],['Guardrails','Week 4 retention and error-free first-session completion, each divided by all assigned users. Both must have a 95% difference interval lower bound above −2 pp. This conservative demonstration does not apply a multiplicity correction; a production protocol would pre-specify family-wise error control and rollout risk.'],['Budget sandbox','For each channel, R(b)=a × [1−exp(−b/k)] / [1−exp(−b₀/k)], where a is observed synthetic activations and b₀ is baseline spend. Greedy marginal allocation preserves total spend and keeps every channel within ± the chosen limit.'],['Identification limits','Response curves are assumed, not fitted. First-touch channel comparisons are observational. A/B data are randomized simulations, not real evidence of product impact. Instrumentation, identity resolution, bot exclusion and real experiments would be required before production decisions.']].map(([a,b])=>`<div class="definition"><strong>${a}</strong><p>${b}</p></div>`).join('')}</article><article class="panel"><div class="panel-head"><div><h2>From raw rows to a decision</h2><p>SQLite-compatible examples · aggregated before joins</p></div><button class="button secondary" data-action="download-sql">${icon('download')}SQL</button></div><pre class="code">${esc(window.SOURCE_SQL)}</pre></article><article class="panel"><div class="panel-head"><div><h2>Reproduce the synthetic population</h2><p>Python 3 · standard library · fixed seed ${D.seed}</p></div><button class="button secondary" data-action="download-python">${icon('download')}Python</button></div><pre class="code">${esc(window.SOURCE_PY)}</pre></article></div><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Take the audit trail with you</h2><p>All ${num(D.rows.length)} users, 43 channel definitions and 516 acquisition-cost records.</p></div><div class="filter-left"><button class="button secondary" data-action="export-users">${icon('download')}User CSV</button><button class="button secondary" data-action="export-costs">${icon('download')}Cost CSV</button><button class="button" data-action="export-data">${icon('download')}Full dataset JSON</button></div></div><p class="small" style="line-height:1.9">Source: deterministic synthetic simulation, seed ${D.seed}. Signup cohorts: 20 Jul–11 Oct 2026. Observation snapshot: 19 Oct 2026. No personal, client, Axtria or Lovable production data. No real-world performance claims. The first four signup cohorts form the randomized demonstration study. This is an AI-assisted portfolio prototype, with assumptions and source included for inspection.</p></section>`;}
function render(){nav();$('#page').innerHTML=({overview,channels,experiments,cohorts,methods}[state.page])();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),2600);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Downloaded ${name}`);}
const csvCell=v=>`"${String(v??'').replace(/"/g,'""')}"`;
function csv(name,header,rows){download(name,[header,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function updatePlanner(){const n=A.sampleSize(.4,state.mde);$('#mde-label').textContent=pct(state.mde,0);$('#sample-size').textContent=num(n);$('#planner-detail').textContent=`Baseline 40.0% → target ${pct(.4*(1+state.mde))}. Approximate equal-allocation two-proportion power calculation.`;}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');if(!b)return;
  switch(b.dataset.action){
    case 'navigate':state.page=b.dataset.page;location.hash=state.page;render();window.scrollTo({top:0,behavior:'instant'});break;
    case 'reset':state.weeks=12;state.group='All channels';state.query='';state.tablePage=1;render();break;
    case 'tour':$('#tour').showModal();break;
    case 'close-tour':$('#tour').close();break;
    case 'sort':if(state.sort===b.dataset.sort)state.direction*=-1;else{state.sort=b.dataset.sort;state.direction=-1;}$('#channel-table').innerHTML=channelTable();break;
    case 'table-page':state.tablePage=Number(b.dataset.index);$('#channel-table').innerHTML=channelTable();break;
    case 'saturation':state.saturation=Number(b.dataset.value);$('#budget-section').innerHTML=budgetResult().html;break;
    case 'export-channels':csv('SignalLab_channels.csv',['channel_id','channel','group','signups','activated_7d','activation_rate','retained_w4','eligible_w4','retention_w4','acquisition_cost_gbp','cost_per_activation_gbp'],channelRows().map(c=>[c.id,c.name,c.group,c.n,c.act,c.rate,c.ret,c.eligible,c.retRate,c.spend,c.cpa]));break;
    case 'export-budget':{const o=budgetResult().o;csv('SignalLab_hypothetical_budget.csv',['channel','baseline_spend_gbp','scenario_spend_gbp','change_fraction','modelled_activations','assumed_saturation_multiple'],o.rows.map(c=>[c.name,c.spend,c.allocated,c.change,c.expected,state.saturation]));break;}
    case 'experiment-mode':state.custom=b.dataset.mode==='custom';render();break;
    case 'calculate-experiment':{const n1=Number($('#n0').value),n2=Number($('#n1').value),x1=Number($('#x0').value),x2=Number($('#x1').value);const vals=[n1,n2,x1,x2];if(['n0','n1','x0','x1'].some(id=>!$('#'+id).value.trim())||vals.some(v=>!Number.isInteger(v))||n1<1||n2<1||n1>10000000||n2>10000000||x1<0||x2<0||x1>n1||x2>n2){$('#input-error').textContent='Enter whole numbers: 1–10,000,000 assigned users per arm, and activations between zero and assigned users.';$('#custom-results').innerHTML='';break;}$('#input-error').textContent='';$('#custom-results').innerHTML=experimentResults({arms:[{n:n1,act:x1},{n:n2,act:x2}],result:A.compare(x1,n1,x2,n2)},true);break;}
    case 'download-sql':download('SignalLab_metrics.sql',window.SOURCE_SQL);break;
    case 'download-python':download('generate_data.py',window.SOURCE_PY);break;
    case 'export-users':csv('SignalLab_synthetic_users.csv',D.fields,D.rows);break;
    case 'export-costs':csv('SignalLab_channel_costs.csv',['signup_week','channel_id','acquisition_cost_gbp'],D.costs);break;
    case 'export-data':download('SignalLab_synthetic_dataset.json',JSON.stringify(D),'application/json');break;
  }
});
document.addEventListener('change',event=>{if(event.target.id==='period'){state.weeks=Number(event.target.value);state.tablePage=1;render();}if(event.target.id==='group'){state.group=event.target.value;state.tablePage=1;render();}});
document.addEventListener('input',event=>{if(event.target.id==='channel-search'){state.query=event.target.value;state.tablePage=1;$('#channel-table').innerHTML=channelTable();}if(event.target.id==='budget-slider'){state.budgetFraction=Number(event.target.value)/100;const v=event.target.value;const active=event.target;const out=budgetResult();$('#budget-lift').textContent='+'+pct(out.o.lift);active.parentElement.querySelector('.range-value').textContent='±'+v+'%';}if(event.target.id==='mde-slider'){state.mde=Number(event.target.value)/100;updatePlanner();}});
// Render the complete allocation list when a slider gesture completes.
document.addEventListener('change',event=>{if(event.target.id==='budget-slider')$('#budget-section').innerHTML=budgetResult().html;});
const tip=$('#chart-tooltip');document.addEventListener('pointerover',event=>{const t=event.target.closest('[data-tooltip]');if(t){tip.textContent=t.dataset.tooltip;tip.style.display='block';const rect=t.getBoundingClientRect();tip.style.left=Math.max(10,Math.min(window.innerWidth-220,rect.left+6))+'px';tip.style.top=Math.max(10,rect.top-72)+'px';}});document.addEventListener('pointerout',event=>{if(event.target.closest('[data-tooltip]'))tip.style.display='none';});
document.addEventListener('focusin',event=>{const t=event.target.closest('[data-tooltip]');if(t){tip.textContent=t.dataset.tooltip;tip.style.display='block';const rect=t.getBoundingClientRect();tip.style.left=Math.min(window.innerWidth-220,rect.left)+'px';tip.style.top=Math.max(5,rect.top-72)+'px';}});document.addEventListener('focusout',()=>tip.style.display='none');
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(titles[p]&&p!==state.page){state.page=p;render();}});
render();
})();
